[element] {
  background: color-mix(in srgb,
    color-mix(in srgb, var(--tint, var(--bg, transparent)) 20%, var(--bg, transparent))
    var(--bg-alpha, 100%),
    transparent
  );
  color: var(--fg, inherit);
  border-color: color-mix(in srgb,
    var(--tint, var(--border-color, transparent)) 30%,
    var(--border-color, transparent)
  );
}

/* the parent publishes */
[element="surface--card"] > [element], [element="surface--card"] > [layout], [element="surface--card"] > [data-part] {
  --parent-pad-x: var(--spacing-lg); --parent-pad-y: var(--spacing-md);
  --parent-radius-tl: …; --parent-border-width: …; --parent-gap: …;
}

/* the children bleed (column parent, the sides always) */
:where([element="surface--card"]):not([data-dir="row"]) > :is([element^="surface--"], [element^="list--"], [element^="table--"], [layout="stack"]) {
  margin-left: calc(-1 * var(--parent-pad-x, 0px));
  margin-right: calc(-1 * var(--parent-pad-x, 0px));
}
:where(:where([element="surface--card"]):not([data-dir="row"])) > :is(…) {
  padding-left: var(--parent-pad-x, 0px);   /* the default; the part's own padding wins */
  padding-right: var(--parent-pad-x, 0px);
}
